const StepDetailsModal = ({
  stepData,
  levelName,
  stepIndex,
  onSave,
  onCancel,
  levelId,
  unitId,
  challengeId,
  curriculumType,
}) => {
  const [content, setContent] = useState(stepData.content);
  const [isUploading, setIsUploading] = useState(false);
  const textAreaRef = useRef(null);

  useEffect(() => {
    if (
      stepData.content === null &&
      levelId &&
      stepData.id &&
      !stepData.id.startsWith("id_")
    ) {
      getDoc(
        doc(
          db,
          "codingLevels",
          levelId,
          curriculumType,
          unitId,
          "challenges",
          challengeId,
          "steps",
          stepData.id
        )
      )
        .then((snap) => {
          if (snap.exists()) setContent(snap.data().content || "");
          else setContent("");
        })
        .catch((err) => console.error("Error fetching step:", err));
    }
  }, [stepData, levelId, curriculumType, unitId, challengeId]);

  const applyStyle = (style, value = null) => {
    const textarea = textAreaRef.current;
    if (!textarea) return;
    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = content ? content.substring(start, end) : "";
    let tag = "";
    switch (style) {
      case "bold":
        tag = `<b>${selectedText}</b>`;
        break;
      case "italic":
        tag = `<i>${selectedText}</i>`;
        break;
      case "h2":
        tag = `<h2>${selectedText}</h2>`;
        break;
      case "color":
        tag = `<span style="color:${value}">${selectedText}</span>`;
        break;
      case "image":
        const url = prompt("Image URL:");
        if (url)
          tag = `<img src="${url}" style="max-width:100%; border-radius:8px; my-2"/>`;
        break;
      default:
        return;
    }
    if (tag)
      setContent(
        (content || "").substring(0, start) +
          tag +
          (content || "").substring(end)
      );
  };

  return (
    <Modal
      title={`Edit ${levelName} - Step ${stepIndex + 1}`}
      onClose={onCancel}
      maxWidth="max-w-4xl"
      footer={
        <>
          <Button variant="secondary" onClick={onCancel}>
            Cancel
          </Button>
          <Button onClick={() => onSave({ ...stepData, content })}>
            Save Changes
          </Button>
        </>
      }>
      <div className="border border-slate-200 rounded-lg flex flex-col h-96">
        <EditorToolbar onAction={applyStyle} />
        <textarea
          ref={textAreaRef}
          value={content || ""}
          onChange={(e) => setContent(e.target.value)}
          className="flex-grow p-3 outline-none resize-none font-mono text-sm"
          placeholder="Enter step content (HTML/Text)..."
        />
        {isUploading && (
          <div className="absolute inset-0 bg-white/80 flex items-center justify-center">
            <Loader2 className="animate-spin" />
          </div>
        )}
      </div>
    </Modal>
  );
};

