const SimplePreviewView = ({ oldCurriculum, newCurriculum }) => {
  const differences = useMemo(() => {
    const diffs = [];
    const getUnits = (curr) =>
      new Map((curr || []).map((u) => [u.unitName, u]));
    const oldMap = getUnits(oldCurriculum);
    const newMap = getUnits(newCurriculum);
    const allNames = new Set([...oldMap.keys(), ...newMap.keys()]);
    allNames.forEach((name) => {
      const o = oldMap.get(name);
      const n = newMap.get(name);
      if (!o && n)
        diffs.push({ type: "Added", msg: `Unit "${name}" was added.` });
      else if (o && !n)
        diffs.push({ type: "Deleted", msg: `Unit "${name}" was removed.` });
      else if (o && n) {
        const getChalls = (u) =>
          new Map(u.challenges.map((c) => [c.challengeName, c]));
        const ocMap = getChalls(o);
        const ncMap = getChalls(n);
        const allChalls = new Set([...ocMap.keys(), ...ncMap.keys()]);
        allChalls.forEach((cName) => {
          if (!ocMap.get(cName) && ncMap.get(cName))
            diffs.push({
              type: "Added",
              msg: `Challenge "${cName}" added to ${name}.`,
            });
          else if (ocMap.get(cName) && !ncMap.get(cName))
            diffs.push({
              type: "Deleted",
              msg: `Challenge "${cName}" removed from ${name}.`,
            });
        });
      }
    });
    return diffs;
  }, [oldCurriculum, newCurriculum]);
  return (
    <Card className="h-full overflow-y-auto">
      <h3 className="text-xl font-bold text-slate-800 mb-6">
        Curriculum Diff Report
      </h3>
      {differences.length === 0 ? (
        <div className="text-center text-slate-500 py-10">
          No structural differences found.
        </div>
      ) : (
        <div className="space-y-3">
          {differences.map((diff, i) => (
            <div
              key={i}
              className={`p-3 rounded-lg border-l-4 flex items-center gap-3 ${
                diff.type === "Added"
                  ? "bg-emerald-50 border-emerald-500"
                  : "bg-red-50 border-red-500"
              }`}>
              {diff.type === "Added" ? (
                <PlusCircle className="text-emerald-600" />
              ) : (
                <Trash2 className="text-red-600" />
              )}
              <span className="text-slate-700">{diff.msg}</span>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
};

const ChallengeComparisonRow = ({
  challenge,
  onAcknowledge,
  userRole,
  username,
  levelId,
  unitId,
  curriculumType,
}) => {
  const [expanded, setExpanded] = useState(false);
  const [difficulty, setDifficulty] = useState("easy");
  const [stepIdx, setStepIdx] = useState(0);
  const [allSteps, setAllSteps] = useState([]);
  const [loadingSteps, setLoadingSteps] = useState(false);
  const status = challenge.acknowledgements?.[username?.toLowerCase()]?.status;

  const steps = useMemo(() => {
    return allSteps
      .filter((s) => s.difficulty?.toLowerCase() === difficulty.toLowerCase())
      .sort((a, b) => (a.stepIndex || 0) - (b.stepIndex || 0));
  }, [allSteps, difficulty]);
  const step = steps[stepIdx];

  useEffect(() => {
    setStepIdx(0);
  }, [difficulty]);

  useEffect(() => {
    if (expanded && challenge.id && allSteps.length === 0) {
      setLoadingSteps(true);
      if (challenge.levels?.easy?.stepDetails?.length > 0) {
        const easy = challenge.levels.easy.stepDetails || [];
        const mod = challenge.levels.moderate?.stepDetails || [];
        const hard = challenge.levels.hard?.stepDetails || [];
        setAllSteps([...easy, ...mod, ...hard]);
        setLoadingSteps(false);
      } else {
        getDocs(
          collection(
            db,
            "codingLevels",
            levelId,
            curriculumType,
            unitId,
            "challenges",
            challenge.id,
            "steps"
          )
        )
          .then((snap) => {
            const loaded = [];
            snap.forEach((d) => loaded.push({ id: d.id, ...d.data() }));
            setAllSteps(loaded);
            setLoadingSteps(false);
          })
          .catch((err) => {
            console.error(err);
            setLoadingSteps(false);
          });
      }
    }
  }, [
    expanded,
    challenge.id,
    levelId,
    unitId,
    curriculumType,
    allSteps.length,
    challenge.levels,
  ]);

  return (
    <div className="border border-slate-200 rounded-lg mb-3 bg-white shadow-sm">
      <div className="sticky top-0 z-20 bg-white border-b border-slate-100 rounded-t-lg">
        <div
          className="p-3 flex justify-between items-center cursor-pointer hover:bg-slate-50 transition-colors"
          onClick={() => setExpanded(!expanded)}>
          <div className="flex items-center gap-3">
            {expanded ? (
              <ChevronUp size={16} className="text-indigo-500" />
            ) : (
              <ChevronDown size={16} className="text-slate-400" />
            )}
            <span
              className={`font-bold text-sm ${
                expanded ? "text-indigo-700" : "text-slate-700"
              }`}>
              {challenge.challengeName || "Untitled"}
            </span>
          </div>
          <div className="flex items-center gap-2">
            {status && <Badge status={status} />}
            {userRole === "teacher" && !status && onAcknowledge && (
              <Button
                variant="primary"
                className="h-7 px-3 text-xs"
                onClick={(e) => {
                  e.stopPropagation();
                  onAcknowledge(challenge.id);
                }}>
                Submit
              </Button>
            )}
          </div>
        </div>
        {expanded && (
          <div className="px-4 py-2 bg-white flex gap-2 border-t border-slate-50">
            {["easy", "moderate", "hard"].map((d) => (
              <button
                key={d}
                onClick={() => setDifficulty(d)}
                className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider transition-all ${
                  difficulty === d
                    ? "bg-violet-100 text-violet-700 ring-1 ring-violet-200"
                    : "bg-slate-100 text-slate-500 hover:bg-slate-200"
                }`}>
                {d}
              </button>
            ))}
          </div>
        )}
      </div>
      {expanded && (
        <div className="p-4 bg-slate-50/50 rounded-b-lg">
          {loadingSteps ? (
            <div className="flex justify-center p-4">
              <Loader2 className="animate-spin text-violet-500" />
            </div>
          ) : (
            <div className="space-y-3">
              <div className="flex items-center gap-2 bg-white p-2 rounded-lg border border-slate-200 shadow-sm w-fit">
                <AlignLeft size={14} className="text-slate-400 ml-1" />
                <select
                  className="bg-transparent text-sm font-medium text-slate-700 outline-none cursor-pointer min-w-[100px]"
                  value={stepIdx}
                  onChange={(e) => setStepIdx(Number(e.target.value))}>
                  {steps.length === 0 ? (
                    <option>No steps</option>
                  ) : (
                    steps.map((_, i) => (
                      <option key={i} value={i}>
                        Step {i + 1}
                      </option>
                    ))
                  )}
                </select>
              </div>
              <div className="bg-white p-5 rounded-xl border border-slate-200 min-h-[150px] text-sm text-slate-700 prose prose-sm max-w-none shadow-sm">
                {step?.content ? (
                  <div dangerouslySetInnerHTML={{ __html: step.content }} />
                ) : (
                  <div className="flex flex-col items-center justify-center h-32 text-slate-400">
                    <FileText size={24} className="mb-2 opacity-20" />
                    <p className="text-xs">
                      No content available for this step.
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

const CurriculumComparisonView = ({ levelId, onBack, userRole }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;
  const [oldUnits, setOldUnits] = useState([]);
  const [newUnits, setNewUnits] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const { currentUser, logActivity } = useAppState();

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    try {
      const fetchShallow = async (coll) => {
        const uSnap = await getDocs(
          collection(db, "codingLevels", levelId, coll)
        );
        const units = [];
        for (const uDoc of uSnap.docs) {
          const unit = { id: uDoc.id, ...uDoc.data(), challenges: [] };
          const cSnap = await getDocs(collection(uDoc.ref, "challenges"));
          unit.challenges = cSnap.docs.map((c) => ({
            id: c.id,
            ...c.data(),
            levels: { easy: {}, moderate: {}, hard: {} },
          }));
          units.push(unit);
        }
        return units.sort(
          (a, b) => parseInt(a.unitNumber || 0) - parseInt(b.unitNumber || 0)
        );
      };
      const [oldD, newD] = await Promise.all([
        fetchShallow("units_old"),
        fetchShallow("units_new"),
      ]);
      setOldUnits(oldD);
      setNewUnits(newD);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  }, [levelId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const flattenCurriculum = (units) => {
    const flat = [];
    units.forEach((u) => {
      if (u.challenges.length === 0)
        flat.push({ type: "unit_header", unit: u, challenge: null });
      u.challenges.forEach((c, idx) => {
        flat.push({
          type: idx === 0 ? "unit_header" : "challenge",
          unit: u,
          challenge: c,
        });
      });
    });
    return flat;
  };

  const oldFlat = useMemo(() => flattenCurriculum(oldUnits), [oldUnits]);
  const newFlat = useMemo(() => flattenCurriculum(newUnits), [newUnits]);
  const totalPages = Math.ceil(
    Math.max(oldFlat.length, newFlat.length) / itemsPerPage
  );
  const paginatedOld = oldFlat.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );
  const paginatedNew = newFlat.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  const handleAck = async (cId) => {
    try {
      let targetUnit = newUnits.find((u) =>
        u.challenges.some((c) => c.id === cId)
      );
      if (!targetUnit) return;
      const challengeRef = doc(
        db,
        "codingLevels",
        levelId,
        "units_new",
        targetUnit.id,
        "challenges",
        cId
      );
      const challengeDoc = await getDoc(challengeRef);
      if (challengeDoc.exists()) {
        const currentAcks = challengeDoc.data().acknowledgements || {};
        const username = currentUser.username.toLowerCase();
        const newAck = { status: "pending", submittedAt: serverTimestamp() };
        await updateDoc(challengeRef, {
          acknowledgements: { ...currentAcks, [username]: newAck },
        });
        await logActivity(username, "submitted_challenge", {
          challengeId: cId,
          levelId,
        });
        fetchData();
        alert("Submitted for review!");
      }
    } catch (e) {
      console.error(e);
    }
  };

  const renderRow = (item, isNew) => {
    if (!item) return <div className="h-16 mb-3"></div>;
    return (
      <div key={item.challenge?.id || item.unit.id}>
        {item.type === "unit_header" && (
          <h4 className="font-bold text-slate-500 text-xs uppercase tracking-wider mb-2 mt-4 border-b border-slate-200 pb-1">
            {item.unit.unitNumber ? `Unit ${item.unit.unitNumber}: ` : ""}
            {item.unit.unitName}
          </h4>
        )}
        {item.challenge && (
          <ChallengeComparisonRow
            challenge={item.challenge}
            onAcknowledge={isNew ? handleAck : undefined}
            userRole={userRole}
            username={currentUser.username}
            levelId={levelId}
            unitId={item.unit.id}
            curriculumType={isNew ? "units_new" : "units_old"}
          />
        )}
      </div>
    );
  };

  return (
    <div className="h-full flex flex-col">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <Button variant="ghost" onClick={onBack}>
            <ArrowLeft size={20} />
          </Button>
          <h2 className="text-xl font-bold text-slate-800">
            Curriculum Comparison
          </h2>
        </div>
        <div className="flex items-center gap-2 bg-white p-1 rounded-lg shadow-sm border border-slate-200">
          <button
            disabled={currentPage === 1}
            onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
            className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
            <ChevronLeft size={20} />
          </button>
          <span className="text-sm font-medium text-slate-600 px-2">
            Page {currentPage} / {totalPages || 1}
          </span>
          <button
            disabled={currentPage >= totalPages}
            onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
            className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
            <ChevronRight size={20} />
          </button>
        </div>
      </div>
      {isLoading ? (
        <div className="flex-1 flex items-center justify-center">
          <Loader2 className="animate-spin text-violet-500" size={40} />
        </div>
      ) : (
        <div className="flex-1 flex gap-6 overflow-hidden">
          <Card className="flex-1 flex flex-col bg-slate-50 border-dashed overflow-hidden">
            <h3 className="font-bold text-slate-500 mb-4 uppercase text-center">
              Old Curriculum
            </h3>
            <div className="overflow-y-auto pr-2 flex-1">
              {paginatedOld.map((item) => renderRow(item, false))}
              {paginatedOld.length === 0 && (
                <p className="text-center text-slate-400 mt-10">End of list</p>
              )}
            </div>
          </Card>
          <Card className="flex-1 flex flex-col border-indigo-200 overflow-hidden shadow-md">
            <h3 className="font-bold text-indigo-600 mb-4 uppercase text-center">
              New Curriculum
            </h3>
            <div className="overflow-y-auto pr-2 flex-1">
              {paginatedNew.map((item) => renderRow(item, true))}
              {paginatedNew.length === 0 && (
                <p className="text-center text-slate-400 mt-10">End of list</p>
              )}
            </div>
          </Card>
        </div>
      )}
    </div>
  );
};

const CurriculumEditor = ({ levelId, onBack }) => {
  const [units, setUnits] = useState([]);
  const [activeUnitIndex, setActiveUnitIndex] = useState(0);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [editStep, setEditStep] = useState(null);

  const loadData = useCallback(async () => {
    setIsLoading(true);
    try {
      const unitsRef = collection(db, "codingLevels", levelId, "units_new");
      const snap = await getDocs(unitsRef);
      const loadedUnits = [];
      for (const d of snap.docs) {
        const unit = { id: d.id, ...d.data(), challenges: [] };
        const challSnap = await getDocs(collection(d.ref, "challenges"));
        for (const cDoc of challSnap.docs) {
          const c = cDoc.data();
          const ch = {
            id: cDoc.id,
            ...c,
            levels: { easy: {}, moderate: {}, hard: {} },
          };
          ["easy", "moderate", "hard"].forEach((d) => {
            ch.levels[d] = { steps: c[`steps_${d}`] || 0, stepDetails: [] };
          });
          unit.challenges.push(ch);
        }
        loadedUnits.push(unit);
      }
      loadedUnits.sort(
        (a, b) => parseInt(a.unitNumber || 0) - parseInt(b.unitNumber || 0)
      );
      setUnits(loadedUnits);
    } catch (e) {
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  }, [levelId]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleSaveUnit = async (unit) => {
    setIsSaving(true);
    try {
      const unitRef = doc(db, "codingLevels", levelId, "units_new", unit.id);
      await setDoc(unitRef, {
        unitNumber: unit.unitNumber,
        unitName: unit.unitName,
      });
      for (const ch of unit.challenges) {
        const chRef = doc(unitRef, "challenges", ch.id);
        const { id, ...data } = ch;
        await setDoc(chRef, data);
      }
      alert("Unit Saved!");
    } catch (e) {
      console.error("Save failed", e);
    } finally {
      setIsSaving(false);
    }
  };

  const handleAddUnit = () => {
    const newUnit = createNewUnit();
    setUnits((prev) => [...prev, newUnit]);
    setActiveUnitIndex(units.length);
  };

  const activeUnit = units[activeUnitIndex];

  return (
    <div className="h-[calc(100vh-120px)] flex flex-col">
      {editStep && (
        <StepDetailsModal
          stepData={editStep.data}
          levelName={editStep.levelName}
          stepIndex={editStep.index}
          levelId={levelId}
          unitId={activeUnit.id}
          challengeId={editStep.challengeId}
          curriculumType="units_new"
          onCancel={() => setEditStep(null)}
          onSave={(newData) => {
            const stepRef = doc(
              db,
              "codingLevels",
              levelId,
              "units_new",
              activeUnit.id,
              "challenges",
              editStep.challengeId,
              "steps",
              newData.id
            );
            setDoc(
              stepRef,
              {
                content: newData.content,
                difficulty: editStep.levelName,
                stepIndex: editStep.index,
              },
              { merge: true }
            );
            setEditStep(null);
          }}
        />
      )}
      <div className="flex justify-between items-center mb-4">
        <div className="flex items-center gap-3">
          <Button variant="ghost" onClick={onBack} className="px-2">
            <ArrowLeft size={20} />
          </Button>
          <h2 className="text-xl font-bold text-slate-800">Editing Level</h2>
        </div>
        <Button onClick={handleAddUnit}>
          <Plus size={18} /> New Unit
        </Button>
      </div>
      <div className="flex flex-grow gap-6 overflow-hidden">
        <Card className="w-64 flex flex-col p-0 overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h3 className="font-bold text-slate-700">Units</h3>
          </div>
          <div className="overflow-y-auto flex-1 p-2 space-y-1">
            {units.map((u, idx) => (
              <button
                key={u.id}
                onClick={() => setActiveUnitIndex(idx)}
                className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                  idx === activeUnitIndex
                    ? "bg-violet-50 text-violet-700"
                    : "text-slate-600 hover:bg-slate-50"
                }`}>
                {u.unitNumber ? `Unit ${u.unitNumber}` : "Untitled Unit"}
              </button>
            ))}
          </div>
        </Card>
        <Card className="flex-1 flex flex-col overflow-hidden p-0">
          {isLoading ? (
            <div className="flex-1 flex items-center justify-center">
              <Loader2 className="animate-spin" />
            </div>
          ) : activeUnit ? (
            <div className="flex flex-col h-full">
              <div className="p-6 border-b border-slate-100 flex gap-4 items-end bg-slate-50/50">
                <div className="w-24">
                  <InputField
                    label="Number"
                    value={activeUnit.unitNumber}
                    onChange={(e) => {
                      const newUnits = [...units];
                      newUnits[activeUnitIndex].unitNumber = e.target.value;
                      setUnits(newUnits);
                    }}
                  />
                </div>
                <div className="flex-1">
                  <InputField
                    label="Unit Name"
                    value={activeUnit.unitName}
                    onChange={(e) => {
                      const newUnits = [...units];
                      newUnits[activeUnitIndex].unitName = e.target.value;
                      setUnits(newUnits);
                    }}
                  />
                </div>
                <Button
                  onClick={() => handleSaveUnit(activeUnit)}
                  disabled={isSaving}>
                  {isSaving ? (
                    <Loader2 className="animate-spin" size={18} />
                  ) : (
                    <Save size={18} />
                  )}{" "}
                  Save Unit
                </Button>
              </div>
              <div className="flex-1 overflow-y-auto p-6">
                <h4 className="font-bold text-slate-800 mb-4">Challenges</h4>
                <div className="grid gap-4">
                  {activeUnit.challenges.map((ch, cIdx) => (
                    <div
                      key={ch.id}
                      className="border border-slate-200 rounded-lg p-4">
                      <div className="flex justify-between mb-3">
                        <span className="font-bold">Challenge {cIdx + 1}</span>
                      </div>
                      <InputField
                        placeholder="Challenge Name"
                        value={ch.challengeName}
                        onChange={(e) => {
                          const newUnits = [...units];
                          newUnits[activeUnitIndex].challenges[
                            cIdx
                          ].challengeName = e.target.value;
                          setUnits(newUnits);
                        }}
                      />
                      <div className="mt-3 flex gap-2">
                        {["easy", "moderate", "hard"].map((lvl) => (
                          <div
                            key={lvl}
                            className="flex items-center gap-2 bg-slate-50 p-2 rounded">
                            <span className="text-xs font-bold uppercase text-slate-500">
                              {lvl}
                            </span>
                            <input
                              type="number"
                              className="w-12 text-xs p-1 border rounded"
                              value={ch.levels?.[lvl]?.steps || 0}
                              onChange={(e) => {
                                const newUnits = [...units];
                                newUnits[activeUnitIndex].challenges[
                                  cIdx
                                ].levels[lvl].steps = parseInt(e.target.value);
                                setUnits(newUnits);
                              }}
                            />
                            <button
                              className="text-xs text-blue-600 hover:underline"
                              onClick={() =>
                                setEditStep({
                                  data: { id: generateId(), content: null },
                                  levelName: lvl,
                                  index: 0,
                                  challengeId: ch.id,
                                })
                              }>
                              Edit Steps
                            </button>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                  <button
                    onClick={() => {
                      const newUnits = [...units];
                      newUnits[activeUnitIndex].challenges.push(
                        createNewChallenge()
                      );
                      setUnits(newUnits);
                    }}
                    className="border-2 border-dashed border-slate-200 rounded-lg p-4 text-slate-400 flex items-center justify-center gap-2">
                    <Plus size={20} /> Add Challenge
                  </button>
                </div>
              </div>
            </div>
          ) : (
            <div className="flex-1 flex items-center justify-center text-slate-400">
              Select a unit
            </div>
          )}
        </Card>
      </div>
    </div>
  );
};

// --- 7. VIEW COMPONENTS (Dashboard, Instructors, Tasks, Reviews, Training) ---

const DashboardView = ({
  teachers,
  levels,
  tasks,
  pendingReviewsCount,
  onNavigate,
}) => {
  const pendingTasks = tasks.filter((t) => t.status === "pending").length;
  const [activityLog, setActivityLog] = useState([]);
  useEffect(() => {
    const q = query(
      collection(db, "activityLog"),
      orderBy("timestamp", "desc"),
      limit(10)
    );
    const unsub = onSnapshot(q, (snap) =>
      setActivityLog(snap.docs.map((d) => ({ id: d.id, ...d.data() })))
    );
    return () => unsub();
  }, []);
  const chartData = useMemo(() => {
    const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    const data = days.map((d) => ({ name: d, logins: 0, submissions: 0 }));
    return data.map((d) => ({
      ...d,
      logins: Math.floor(Math.random() * 20),
      submissions: Math.floor(Math.random() * 10),
    }));
  }, [activityLog]);

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <Breadcrumb path={["Dashboard", "Overview"]} />
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        {[
          {
            label: "Instructors",
            val: teachers.length,
            icon: Users,
            col: "text-violet-600",
            bg: "bg-violet-50",
            link: "instructors",
          },
          {
            label: "Levels",
            val: levels.length,
            icon: BookOpen,
            col: "text-blue-600",
            bg: "bg-blue-50",
            link: "materials",
          },
          {
            label: "Pending Tasks",
            val: pendingTasks,
            icon: AlertCircle,
            col: "text-amber-600",
            bg: "bg-amber-50",
            link: "tasks",
          },
          {
            label: "Pending Reviews",
            val: pendingReviewsCount,
            icon: Clock,
            col: "text-indigo-600",
            bg: "bg-indigo-50",
            link: "reviews",
          },
        ].map((s, i) => (
          <Card
            key={i}
            onClick={() => s.link && onNavigate(s.link)}
            className={
              s.link ? "cursor-pointer hover:shadow-md transition-all" : ""
            }>
            <div className="flex justify-between items-start">
              <div>
                <p className="text-sm font-medium text-slate-500">{s.label}</p>
                <h3 className="text-3xl font-bold text-slate-800 mt-2">
                  {s.val}
                </h3>
              </div>
              <div className={`p-3 rounded-xl ${s.bg} ${s.col}`}>
                <s.icon size={24} />
              </div>
            </div>
          </Card>
        ))}
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <Card className="lg:col-span-2 h-80">
          <h3 className="font-bold text-slate-800 mb-6">Activity Overview</h3>
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={chartData}>
              <CartesianGrid
                strokeDasharray="3 3"
                vertical={false}
                stroke="#e2e8f0"
              />
              <XAxis
                dataKey="name"
                axisLine={false}
                tickLine={false}
                tick={{ fill: "#64748b" }}
              />
              <YAxis
                axisLine={false}
                tickLine={false}
                tick={{ fill: "#64748b" }}
              />
              <Tooltip
                contentStyle={{
                  borderRadius: "12px",
                  border: "none",
                  boxShadow: "0 4px 6px -1px rgba(0,0,0,0.1)",
                }}
              />
              <Line
                type="monotone"
                dataKey="logins"
                stroke={COLORS.primary}
                strokeWidth={3}
                dot={{ r: 4 }}
              />
              <Line
                type="monotone"
                dataKey="submissions"
                stroke={COLORS.success}
                strokeWidth={3}
                dot={{ r: 4 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </Card>
        <Card className="h-80 overflow-hidden flex flex-col">
          <h3 className="font-bold text-slate-800 mb-4">
            Recent Activity Feed
          </h3>
          <div className="overflow-y-auto space-y-3 pr-2 flex-1">
            {activityLog.map((log) => (
              <div
                key={log.id}
                className="flex items-start gap-3 p-3 bg-slate-50 rounded-lg border border-slate-100">
                <div
                  className={`mt-1 w-2 h-2 rounded-full flex-shrink-0 ${
                    log.action.includes("login")
                      ? "bg-emerald-500"
                      : "bg-blue-500"
                  }`}
                />
                <div className="min-w-0">
                  <p className="text-sm font-medium text-slate-700 capitalize">
                    {log.username}{" "}
                    <span className="text-slate-400 font-normal">
                      {log.action.replace(/_/g, " ")}
                    </span>
                  </p>
                  <p className="text-xs text-slate-400">
                    {formatTimestamp(log.timestamp)}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
};

