const AdminPanel = () => {
  const { currentUser, logout, login } = useAppState();
  const [activeTab, setActiveTab] = useState("dashboard");
  const [teachers, setTeachers] = useState([]);
  const [levels, setLevels] = useState([]);
  const [tasks, setTasks] = useState([]);

  const [selectedLevelId, setSelectedLevelId] = useState(null);
  const [compareLevelId, setCompareLevelId] = useState(null);
  const [showDiff, setShowDiff] = useState(false);
  const [activeReview, setActiveReview] = useState(null);

  const [assignTaskUser, setAssignTaskUser] = useState(null);
  const [viewLogUser, setViewLogUser] = useState(null);
  const [addEventOpen, setAddEventOpen] = useState(false);

  const [trackingData, setTrackingData] = useState([]);
  const [allPendingReviews, setAllPendingReviews] = useState([]);
  const [loadingTracking, setLoadingTracking] = useState(false);
  const [scheduleEvents, setScheduleEvents] = useState([]);

  useEffect(() => {
    if (!currentUser) return;
    const unsubT = onSnapshot(collection(db, "teachers"), (s) =>
      setTeachers(s.docs.map((d) => ({ id: d.id, ...d.data() })))
    );
    const unsubL = onSnapshot(collection(db, "codingLevels"), (s) =>
      setLevels(s.docs.map((d) => ({ id: d.id, ...d.data() })))
    );
    const unsubK = onSnapshot(collection(db, "tasks"), (s) =>
      setTasks(s.docs.map((d) => ({ id: d.id, ...d.data() })))
    );
    const unsubE = onSnapshot(collection(db, "events"), (s) =>
      setScheduleEvents(s.docs.map((d) => ({ id: d.id, ...d.data() })))
    );
    return () => {
      unsubT();
      unsubL();
      unsubK();
      unsubE();
    };
  }, [currentUser]);

  useEffect(() => {
    if (
      (activeTab === "tracking" ||
        activeTab === "training" ||
        activeTab === "reviews" ||
        activeTab === "dashboard") &&
      levels.length > 0
    ) {
      setLoadingTracking(true);
      const load = async () => {
        const data = await Promise.all(
          levels.map(async (level) => {
            const units = await fetchCurriculumShell(level.id, "units_new");
            return { name: level.name, id: level.id, newData: units };
          })
        );
        setTrackingData(data);
        const pending = [];
        data.forEach((lvl) => {
          lvl.newData.forEach((unit) => {
            unit.challenges.forEach((ch) => {
              if (ch.acknowledgements) {
                Object.entries(ch.acknowledgements).forEach(([user, ack]) => {
                  if (ack.status === "pending") {
                    pending.push({
                      levelId: lvl.id,
                      levelName: lvl.name,
                      unitId: unit.id,
                      unitName: unit.unitName,
                      challengeId: ch.id,
                      challengeName: ch.challengeName,
                      username: user,
                      submittedAt: ack.submittedAt,
                      submissionComments: ch.submissionComments,
                    });
                  }
                });
              }
            });
          });
        });
        setAllPendingReviews(pending);
        setLoadingTracking(false);
      };
      load();
    }
  }, [activeTab, levels]);

  const handleAssignTask = async ({ title, description, assignedTo }) => {
    const batch = writeBatch(db);
    const assignees = Array.isArray(assignedTo) ? assignedTo : [assignedTo];
    assignees.forEach((user) => {
      const ref = doc(collection(db, "tasks"));
      batch.set(ref, {
        title,
        description,
        assignedTo: user,
        status: "pending",
        createdAt: serverTimestamp(),
      });
    });
    await batch.commit();
  };
  const handleAddEvent = async (eventData) => {
    await addDoc(collection(db, "events"), {
      ...eventData,
      createdAt: serverTimestamp(),
    });
    setAddEventOpen(false);
  };
  const handleAddTeacher = async (username) => {
    await addDoc(collection(db, "teachers"), {
      username,
      role: "teacher",
      createdAt: serverTimestamp(),
    });
  };
  const handleDeleteTeacher = async (id) => {
    if (window.confirm("Delete this instructor?"))
      await deleteDoc(doc(db, "teachers", id));
  };
  const handleAddLevel = async () => {
    const name = prompt("Level Name?");
    if (name) await addDoc(collection(db, "codingLevels"), { name });
  };
  const handleDeleteLevel = async (id) => {
    if (window.confirm("Delete level?"))
      await deleteDoc(doc(db, "codingLevels", id));
  };
  const handleReviewAction = async (reviewData, status, comment) => {
    try {
      const { levelId, unitId, challengeId, username } = reviewData;
      const chRef = doc(
        db,
        "codingLevels",
        levelId,
        "units_new",
        unitId,
        "challenges",
        challengeId
      );
      // Optimistic Update in UI
      setAllPendingReviews((prev) =>
        prev.filter(
          (r) => !(r.challengeId === challengeId && r.username === username)
        )
      );

      const snap = await getDoc(chRef);
      if (snap.exists()) {
        const data = snap.data();
        const acks = data.acknowledgements || {};
        const comments = data.submissionComments || {};
        acks[username.toLowerCase()] = {
          status,
          reviewedAt: serverTimestamp(),
        };
        if (comment) comments[username.toLowerCase()] = comment;
        await updateDoc(chRef, {
          acknowledgements: acks,
          submissionComments: comments,
        });
        setActiveReview(null);
      }
    } catch (e) {
      console.error(e);
    }
  };

  const handleUpdateTrainingStatus = async (teacherId, levelId, newStatus) => {
    const teacherRef = doc(db, "teachers", teacherId);
    await setDoc(
      teacherRef,
      { trainingStatus: { [levelId]: newStatus } },
      { merge: true }
    );
  };

  const renderContent = () => {
    if (compareLevelId)
      return (
        <CurriculumComparisonView
          levelId={compareLevelId}
          onBack={() => setCompareLevelId(null)}
          userRole="admin"
        />
      );
    if (selectedLevelId)
      return (
        <CurriculumEditor
          levelId={selectedLevelId}
          onBack={() => setSelectedLevelId(null)}
        />
      );

    switch (activeTab) {
      case "dashboard":
        return (
          <DashboardView
            teachers={teachers}
            levels={levels}
            tasks={tasks}
            pendingReviewsCount={allPendingReviews.length}
            onNavigate={setActiveTab}
          />
        );
      case "instructors":
        return (
          <InstructorsView
            teachers={teachers}
            onAddTeacher={handleAddTeacher}
            onDeleteTeacher={handleDeleteTeacher}
            onAssignTask={setAssignTaskUser}
            onViewLog={setViewLogUser}
          />
        );
      case "tasks":
        return (
          <TasksView
            tasks={tasks}
            teachers={teachers}
            onAddTask={() => setAssignTaskUser({})}
          />
        );
      case "reviews":
        return (
          <PendingReviewsView
            pendingReviews={allPendingReviews}
            onOpenReview={setActiveReview}
          />
        );
      case "tracking":
        return (
          <TeacherTrackingView
            allLevels={trackingData}
            teachers={teachers}
            onAssignTask={setAssignTaskUser}
            onViewLog={setViewLogUser}
            isLoading={loadingTracking}
          />
        );
      case "training":
        return (
          <TrainingManagementView
            allLevels={trackingData}
            teachers={teachers}
            onUpdateStatus={handleUpdateTrainingStatus}
          />
        );
      case "materials":
        return (
          <div className="space-y-6 animate-in fade-in">
            <Breadcrumb path={["Curriculum", "Materials"]} />
            <div className="flex justify-between">
              <h2 className="text-xl font-bold">Curriculum</h2>
              <Button
                onClick={() => setShowDiff(!showDiff)}
                variant="secondary">
                <ListChecks size={18} />{" "}
                {showDiff ? "View Grid" : "Diff Report"}
              </Button>
            </div>
            {showDiff ? (
              <SimplePreviewView oldCurriculum={[]} newCurriculum={[]} />
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {levels.map((l) => (
                  <Card key={l.id}>
                    <h3 className="font-bold text-lg">{l.name}</h3>
                    <div className="flex gap-2 mt-4">
                      <Button
                        className="flex-1 h-8 text-xs"
                        onClick={() => setSelectedLevelId(l.id)}>
                        Edit
                      </Button>
                      <Button
                        className="flex-1 h-8 text-xs"
                        variant="secondary"
                        onClick={() => setCompareLevelId(l.id)}>
                        Compare
                      </Button>
                    </div>
                    <div className="mt-2 flex justify-end">
                      <button
                        onClick={() => handleDeleteLevel(l.id)}
                        className="text-red-400 hover:text-red-600">
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </Card>
                ))}
                <button
                  onClick={handleAddLevel}
                  className="border-2 border-dashed border-slate-300 rounded-xl flex flex-col items-center justify-center p-6 text-slate-400 hover:border-violet-400 hover:text-violet-500 transition-colors">
                  <Plus size={32} />
                  <span>Create New Level</span>
                </button>
              </div>
            )}
          </div>
        );
      case "schedule":
        return (
          <ScheduleView
            tasks={tasks}
            events={scheduleEvents}
            teachers={teachers}
            onAddEvent={() => setAddEventOpen(true)}
          />
        );
      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      {assignTaskUser && (
        <AssignTaskModal
          teacher={assignTaskUser}
          teachers={teachers}
          onClose={() => setAssignTaskUser(null)}
          onAssign={handleAssignTask}
        />
      )}
      {viewLogUser && (
        <ActivityLogModal
          teacher={viewLogUser}
          onClose={() => setViewLogUser(null)}
        />
      )}
      {activeReview && (
        <ReviewSubmissionModal
          review={activeReview}
          onClose={() => setActiveReview(null)}
          onReviewAction={handleReviewAction}
        />
      )}
      {addEventOpen && (
        <AddEventModal
          teachers={teachers}
          onClose={() => setAddEventOpen(false)}
          onSave={handleAddEvent}
        />
      )}

      <aside className="w-64 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0">
        <div className="p-6 flex items-center gap-3 text-white font-bold text-xl">
          <BookOpen className="text-violet-500" /> Training Dashboard
        </div>
        <nav className="flex-1 px-4 space-y-2 mt-4">
          {[
            { id: "dashboard", l: "Dashboard", i: LayoutDashboard },
            { id: "tasks", l: "Tasks", i: CheckSquare },
            { id: "reviews", l: "Reviews", i: Clock },
            { id: "instructors", l: "Instructors", i: Users },
            { id: "tracking", l: "Progress", i: Activity },
            { id: "training", l: "Training Flow", i: GraduationCap },
            { id: "materials", l: "Curriculum", i: BookOpen },
            { id: "schedule", l: "Schedule", i: CalendarIcon },
          ].map((item) => (
            <button
              key={item.id}
              onClick={() => {
                setActiveTab(item.id);
                setCompareLevelId(null);
                setSelectedLevelId(null);
              }}
              className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
                activeTab === item.id
                  ? "bg-violet-600 text-white shadow-lg shadow-violet-900/50"
                  : "hover:bg-slate-800"
              }`}>
              <item.i size={20} /> {item.l}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-slate-800">
          <button
            onClick={logout}
            className="flex items-center gap-2 text-red-400 hover:text-white w-full px-4 py-2">
            <LogOut size={18} /> Sign Out
          </button>
        </div>
      </aside>
      <main className="flex-1 p-8 overflow-y-auto h-screen">
        <div className="max-w-7xl mx-auto h-full">
          <header className="flex justify-between items-center mb-8 bg-gray/80 backdrop-blur-md p-4 rounded-xl shadow-lg border border-white/50 sticky top-0 z-10">
            <h1 className="text-2xl font-bold text-slate-800 capitalize">
              {activeTab}
            </h1>
            <div className="flex items-center gap-4">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-700">
                  {currentUser?.username}
                </p>
                <p className="text-xs text-slate-500 capitalize">
                  {currentUser?.role}
                </p>
              </div>
              <div className="w-10 h-10 bg-violet-100 rounded-full flex items-center justify-center text-violet-600 font-bold border border-violet-200">
                {currentUser?.username?.[0]}
              </div>
            </div>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

const LoginScreen = () => {
  const { login } = useAppState();
  const [user, setUser] = useState("");
  const [pass, setPass] = useState("");
  const [err, setErr] = useState("");
  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-50">
      <div className="w-96 bg-white p-8 rounded-xl shadow-xl border border-slate-100">
        <div className="text-center mb-8">
          <div className="w-12 h-12 bg-violet-600 rounded-xl flex items-center justify-center mx-auto mb-4 shadow-lg shadow-violet-200">
            <BookOpen className="text-white" size={24} />
          </div>
          <h2 className="text-2xl font-bold text-slate-800">
            Access Your Dashboard
          </h2>
          <p className="text-slate-500">Manage Training Society</p>
        </div>
        <form
          onSubmit={async (e) => {
            e.preventDefault();
            if (!(await login(user, pass))) setErr("Invalid credentials");
          }}
          className="space-y-4">
          <InputField
            label="Username"
            value={user}
            onChange={(e) => setUser(e.target.value)}
          />
          <InputField
            label="Password"
            type="password"
            value={pass}
            onChange={(e) => setPass(e.target.value)}
          />
          {err && <p className="text-red-500 text-sm text-center">{err}</p>}
          <Button className="w-full justify-center py-2.5">Sign In</Button>
        </form>
      </div>
    </div>
  );
};

const TeacherDashboard = () => {
  const { currentUser, logout } = useAppState();
  const [activeTab, setActiveTab] = useState("overview");
  const [levels, setLevels] = useState([]);
  const [tasks, setTasks] = useState([]);
  const [selectedLevelId, setSelectedLevelId] = useState(null);
  const [stats, setStats] = useState({
    levelsFinished: 0,
    challengesSubmitted: 0,
    activeLevels: 0,
  });
  const [rawData, setRawData] = useState([]);

  useEffect(() => {
    const unsubL = onSnapshot(collection(db, "codingLevels"), (s) => {
      const lvlData = s.docs.map((d) => ({ id: d.id, ...d.data() }));
      lvlData.sort(customLevelSort);
      setLevels(lvlData);
    });
    const q = query(
      collection(db, "tasks"),
      where("assignedTo", "==", currentUser.username.toLowerCase())
    );
    const unsubT = onSnapshot(q, (s) =>
      setTasks(s.docs.map((d) => ({ id: d.id, ...d.data() })))
    );
    return () => {
      unsubL();
      unsubT();
    };
  }, [currentUser]);

  useEffect(() => {
    if (levels.length > 0) {
      const loadStats = async () => {
        let totalChallenges = 0,
          submittedCount = 0,
          finishedLevels = 0,
          activeLvlCount = 0;
        const processedData = await Promise.all(
          levels.map(async (level) => {
            const units = await fetchCurriculumShell(level.id, "units_new");
            let levelApproved = 0,
              levelTotal = 0,
              hasActivity = false;
            const processedUnits = units.map((unit) => {
              const procChallenges = unit.challenges.map((ch) => {
                levelTotal++;
                const status =
                  ch.acknowledgements?.[currentUser.username.toLowerCase()]
                    ?.status || "not_started";
                if (status !== "not_started") {
                  submittedCount++;
                  hasActivity = true;
                  if (status === "approved") levelApproved++;
                }
                return { challengeName: ch.challengeName, status };
              });
              return { unitName: unit.unitName, challenges: procChallenges };
            });
            if (levelTotal > 0 && levelApproved === levelTotal)
              finishedLevels++;
            if (hasActivity && levelApproved < levelTotal) activeLvlCount++;
            else if (levelTotal > 0 && !hasActivity) activeLvlCount++;
            return { name: level.name, units: processedUnits };
          })
        );
        setRawData(processedData);
        setStats({
          levelsFinished: finishedLevels,
          challengesSubmitted: submittedCount,
          activeLevels: activeLvlCount,
        });
      };
      loadStats();
    }
  }, [levels, currentUser]);

  if (selectedLevelId)
    return (
      <div className="p-6 h-screen flex flex-col bg-slate-50">
        <CurriculumComparisonView
          levelId={selectedLevelId}
          onBack={() => setSelectedLevelId(null)}
          userRole="teacher"
        />
      </div>
    );

  const renderContent = () => {
    switch (activeTab) {
      case "overview":
        return (
          <TeacherOverview
            stats={stats}
            tasks={tasks}
            onNavigate={setActiveTab}
            rawData={rawData}
          />
        );
      case "curriculum":
        return (
          <TeacherCurriculumList
            levels={levels}
            onSelectLevel={setSelectedLevelId}
          />
        );
      default:
        return (
          <TeacherOverview
            stats={stats}
            tasks={tasks}
            onNavigate={setActiveTab}
            rawData={rawData}
          />
        );
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex">
      <aside className="w-64 bg-slate-900 text-slate-300 flex flex-col flex-shrink-0">
        <div className="p-6 flex items-center gap-3 text-white font-bold text-xl">
          <BookOpen className="text-emerald-500" /> Training
        </div>
        <nav className="flex-1 px-4 space-y-2 mt-4">
          <button
            onClick={() => setActiveTab("overview")}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
              activeTab === "overview"
                ? "bg-emerald-600 text-white shadow-lg"
                : "hover:bg-slate-800"
            }`}>
            <LayoutDashboard size={20} /> Overview
          </button>
          <button
            onClick={() => setActiveTab("curriculum")}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${
              activeTab === "curriculum"
                ? "bg-emerald-600 text-white shadow-lg"
                : "hover:bg-slate-800"
            }`}>
            <BookOpen size={20} /> Curriculum
          </button>
        </nav>
        <div className="p-4 border-t border-slate-800">
          <button
            onClick={logout}
            className="flex items-center gap-2 text-red-400 hover:text-white w-full px-4 py-2">
            <LogOut size={18} /> Sign Out
          </button>
        </div>
      </aside>
      <main className="flex-1 p-8 overflow-y-auto h-screen">
        <div className="max-w-7xl mx-auto h-full">
          <header className="flex justify-between items-center mb-8 bg-white/80 backdrop-blur-md p-4 rounded-xl shadow-sm border border-white/50 sticky top-0 z-10">
            <h1 className="text-2xl font-bold text-slate-800 capitalize">
              {activeTab}
            </h1>
            <div className="flex items-center gap-4">
              <div className="text-right hidden sm:block">
                <p className="text-sm font-bold text-slate-700">
                  {currentUser?.username}
                </p>
                <p className="text-xs text-slate-500 capitalize">Instructor</p>
              </div>
              <div className="w-10 h-10 bg-emerald-100 rounded-full flex items-center justify-center text-emerald-600 font-bold border border-emerald-200">
                {currentUser?.username?.[0]}
              </div>
            </div>
          </header>
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

const AuthWrapper = () => {
  const { currentUser } = useAppState();
  if (!currentUser) return <LoginScreen />;
  if (currentUser.role === "teacher") return <TeacherDashboard />;
  return <AdminPanel />;
};

export default function App() {
  return (
    <AppStateProvider>
      <AuthWrapper />
    </AppStateProvider>
  );
}
